229	static void qspi_exchange(struct spi_dev_s *dev, const void *txbuffer,
230	                          void *rxbuffer, size_t nwords)
231	{
232	  struct bk7258_qspi_dev_s *priv = (struct bk7258_qspi_dev_s *)dev;
233	  const uint8_t *tx = txbuffer;
234	  size_t chunk;
235	
236	  if (tx == NULL)
237	    {
238	      return;
239	    }
240	
241	  while (nwords > 0)
242	    {
243	      chunk = (nwords > QSPI_CHUNK_DATA + 1) ? QSPI_CHUNK_DATA + 1 : nwords;
244	
245	      if (bk7258_qspi_op(priv, tx, chunk) != OK)
246	        {
247	          return;
248	        }
249	
250	      tx     += chunk;
251	      nwords -= chunk;
252	    }
253	}
