/****************************************************************************
 * apps/eyes/eyes_main.c
 *
 * Robot-face eye animation for the contest board's two GC9D01 panels.
 * Everything is drawn procedurally: a glowing iris ring, a pupil that
 * leads the gaze, a fixed specular highlight, and an eyelid for blinks.
 * Only the union of the previous and current iris boxes is redrawn and
 * flushed, so the QSPI path moves a few kilobytes per frame instead of
 * the whole screen.
 *
 * Usage: eyes [seconds]   (0 = run until reset; default 30)
 ****************************************************************************/

#include <nuttx/config.h>
#include <nuttx/video/fb.h>

#include <sys/ioctl.h>
#include <sys/mman.h>
#include <fcntl.h>
#include <stdio.h>
#include <stdint.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>

/****************************************************************************
 * Pre-processor Definitions
 ****************************************************************************/

#define EYE_XRES   160
#define EYE_YRES   160
#define EYE_CX     80
#define EYE_CY     80

#define R_RING     34         /* Outer edge of the glowing ring */
#define R_IRIS     29         /* Inner iris disc */
#define R_PUP      13         /* Pupil */
#define R_HIL      4          /* Specular highlight */
#define G_MAX      18         /* Gaze offset limit for the iris centre */

#define C_BG       0x0000     /* Black face */
#define C_RING     0x07ff     /* Cyan ring */
#define C_IRIS     0x0350     /* Deep teal fill */
#define C_PUP      0x0841     /* Near-black pupil */
#define C_HIL      0xffff     /* White highlight */

#define FRAME_US   33000      /* ~30 fps pacing */

/****************************************************************************
 * Private Types
 ****************************************************************************/

struct eye_fb_s
{
  int fd;
  uint16_t *mem;
  size_t len;
  int stride_px;
};

/****************************************************************************
 * Private Data
 ****************************************************************************/

/* Percent closed per blink phase: shut fast, open a touch slower. */

static const uint8_t g_lidfrac[] =
{
  35, 75, 100, 100, 80, 55, 30, 10, 0
};

/****************************************************************************
 * Private Functions
 ****************************************************************************/

static uint32_t now_ms(void)
{
  struct timespec ts;

  clock_gettime(CLOCK_MONOTONIC, &ts);
  return (uint32_t)(ts.tv_sec * 1000 + ts.tv_nsec / 1000000);
}

/****************************************************************************
 * Name: eye_render
 *
 * Description:
 *   Repaint one rectangle of one eye.  Every pixel in the rectangle is
 *   classified from scratch (lid, highlight, pupil, iris, ring, bg), so
 *   the caller only has to get the dirty box right.
 *
 ****************************************************************************/

static void eye_render(struct eye_fb_s *e, int cx, int cy, int lid,
                       int x0, int y0, int x1, int y1)
{
  /* The pupil leads the gaze slightly and the highlight rides the iris. */

  int px = cx + ((cx - EYE_CX) >> 3);
  int py = cy + ((cy - EYE_CY) >> 3);
  int hx = cx - 11;
  int hy = cy - 11;
  int x;
  int y;

  for (y = y0; y <= y1; y++)
    {
      uint16_t *row = e->mem + y * e->stride_px;

      for (x = x0; x <= x1; x++)
        {
          uint16_t c = C_BG;

          if (y >= lid)
            {
              int dx = x - cx;
              int dy = y - cy;
              int d2 = dx * dx + dy * dy;

              if (d2 <= R_RING * R_RING)
                {
                  int ex = x - hx;
                  int ey = y - hy;
                  int qx = x - px;
                  int qy = y - py;

                  if (ex * ex + ey * ey <= R_HIL * R_HIL)
                    {
                      c = C_HIL;
                    }
                  else if (qx * qx + qy * qy <= R_PUP * R_PUP)
                    {
                      c = C_PUP;
                    }
                  else if (d2 <= R_IRIS * R_IRIS)
                    {
                      c = C_IRIS;
                    }
                  else
                    {
                      c = C_RING;
                    }
                }
            }

          row[x] = c;
        }
    }
}

static int eye_open(struct eye_fb_s *e, const char *path)
{
  struct fb_planeinfo_s pinfo;

  e->fd = open(path, O_RDWR);
  if (e->fd < 0)
    {
      printf("eyes: cannot open %s\n", path);
      return -1;
    }

  if (ioctl(e->fd, FBIOGET_PLANEINFO, (unsigned long)(uintptr_t)&pinfo) < 0)
    {
      printf("eyes: FBIOGET_PLANEINFO failed on %s\n", path);
      close(e->fd);
      return -1;
    }

  e->len = pinfo.fblen;
  e->stride_px = pinfo.stride / 2;
  e->mem = mmap(NULL, pinfo.fblen, PROT_READ | PROT_WRITE,
                MAP_SHARED | MAP_FILE, e->fd, 0);
  if (e->mem == MAP_FAILED)
    {
      printf("eyes: mmap failed on %s\n", path);
      close(e->fd);
      return -1;
    }

  return 0;
}

static void eye_flush(struct eye_fb_s *e, int x0, int y0, int x1, int y1)
{
  struct fb_area_s area;

  area.x = x0;
  area.y = y0;
  area.w = x1 - x0 + 1;
  area.h = y1 - y0 + 1;
  ioctl(e->fd, FBIO_UPDATE, (unsigned long)(uintptr_t)&area);
}

/****************************************************************************
 * Public Functions
 ****************************************************************************/

int main(int argc, char *argv[])
{
  struct eye_fb_s eye[2];
  int duration = (argc > 1) ? atoi(argv[1]) : 30;
  int gx = 0;
  int gy = 0;
  int tx = 0;
  int ty = 0;
  int blink = -1;
  int px0 = 0;
  int py0 = 0;
  int px1 = EYE_XRES - 1;
  int py1 = EYE_YRES - 1;
  uint32_t start;
  uint32_t next_gaze;
  uint32_t next_blink;
  uint32_t frames = 0;
  int i;

  if (eye_open(&eye[0], "/dev/fb0") < 0)
    {
      return 1;
    }

  if (eye_open(&eye[1], "/dev/fb1") < 0)
    {
      munmap(eye[0].mem, eye[0].len);
      close(eye[0].fd);
      return 1;
    }

  srand(now_ms());
  start      = now_ms();
  next_gaze  = start + 1500;
  next_blink = start + 2200;

  for (; ; )
    {
      uint32_t t0 = now_ms();
      int cx;
      int cy;
      int lid;
      int x0;
      int y0;
      int x1;
      int y1;

      if (duration > 0 && (t0 - start) >= (uint32_t)duration * 1000)
        {
          break;
        }

      /* Pick a fresh gaze target now and then (never mid-blink). */

      if (blink < 0 && t0 >= next_gaze)
        {
          do
            {
              tx = rand() % (2 * G_MAX + 1) - G_MAX;
              ty = rand() % (2 * G_MAX + 1) - G_MAX;
            }
          while (tx * tx + ty * ty > G_MAX * G_MAX);

          next_gaze = t0 + 1200 + rand() % 1800;
        }

      /* Ease a quarter of the remaining distance each frame. */

      if (gx != tx)
        {
          int step = (tx - gx) / 4;
          gx += (step != 0) ? step : ((tx > gx) ? 1 : -1);
        }

      if (gy != ty)
        {
          int step = (ty - gy) / 4;
          gy += (step != 0) ? step : ((ty > gy) ? 1 : -1);
        }

      /* Blink state machine: the lid is just a row below which we draw. */

      if (blink < 0 && t0 >= next_blink)
        {
          blink = 0;
        }

      if (blink >= 0)
        {
          lid = (EYE_CY - R_RING) +
                (2 * R_RING * g_lidfrac[blink]) / 100;
          blink++;
          if (blink >= (int)sizeof(g_lidfrac))
            {
              blink = -1;
              next_blink = t0 + 2000 + rand() % 2500;
            }
        }
      else
        {
          lid = 0;
        }

      cx = EYE_CX + gx;
      cy = EYE_CY + gy;

      /* Dirty box: current iris box united with the previous one. */

      x0 = cx - R_RING - 1;
      y0 = cy - R_RING - 1;
      x1 = cx + R_RING + 1;
      y1 = cy + R_RING + 1;

      if (px0 < x0) x0 = px0;
      if (py0 < y0) y0 = py0;
      if (px1 > x1) x1 = px1;
      if (py1 > y1) y1 = py1;

      if (x0 < 0) x0 = 0;
      if (y0 < 0) y0 = 0;
      if (x1 > EYE_XRES - 1) x1 = EYE_XRES - 1;
      if (y1 > EYE_YRES - 1) y1 = EYE_YRES - 1;

      for (i = 0; i < 2; i++)
        {
          eye_render(&eye[i], cx, cy, lid, x0, y0, x1, y1);
          eye_flush(&eye[i], x0, y0, x1, y1);
        }

      px0 = cx - R_RING - 1;
      py0 = cy - R_RING - 1;
      px1 = cx + R_RING + 1;
      py1 = cy + R_RING + 1;

      frames++;

      /* Pace to the frame grid; a slow frame just runs back-to-back. */

      {
        uint32_t spent = now_ms() - t0;

        if (spent * 1000 < FRAME_US)
          {
            usleep(FRAME_US - spent * 1000);
          }
      }
    }

  {
    uint32_t total = now_ms() - start;

    printf("eyes: %lu frames in %lu ms (%lu fps)\n",
           (unsigned long)frames, (unsigned long)total,
           (unsigned long)(total ? frames * 1000 / total : 0));
  }

  for (i = 0; i < 2; i++)
    {
      munmap(eye[i].mem, eye[i].len);
      close(eye[i].fd);
    }

  return 0;
}

/****************************************************************************
 * boards/arm/bk7258/contest_board/chip/bk7258_psram.c
 *
 * Bring-up for the 16 MB APS128XXO_OB9 octal PSRAM.  The sequence is a
 * faithful transcription of the vendor SDK (bk_idk psram_hal.c /
 * psram_driver.c), which is the only register-level documentation that
 * exists: LDO first, then the AHBP power domain, 80 MHz while the die is
 * configured, and 120 MHz only after the mode registers are set.
 *
 * Two SoC quirks matter here:
 *  - ana_reg13 (0x44010134) is an "analog" register: every write must be
 *    followed by polling busy bit 13 of 0x440100e8 until it clears, or
 *    the value silently never lands.
 *  - The controller's sf_reset (REG2 bit0) follows the family convention:
 *    it is a LEVEL, 1 = released.
 ****************************************************************************/

#include <nuttx/config.h>
#include <nuttx/arch.h>
#include <stdint.h>

#include "arm_internal.h"
#include "bk7258_memorymap.h"
#include "bk7258_psram.h"

/****************************************************************************
 * Pre-processor Definitions
 ****************************************************************************/

#define PSRAM_CTRL_BASE       0x46080000ul
#define PSRAM_DATA_BASE       0x60000000ul
#define PSRAM_SIZE            (16ul * 1024 * 1024)

/* Controller registers (word offsets from the SDK psram_ll macros) */

#define PSRAM_REG2            (PSRAM_CTRL_BASE + 0x08)  /* sf_reset, bypass */
#define PSRAM_REG4_MODE       (PSRAM_CTRL_BASE + 0x10)  /* die mode word */
#define PSRAM_REG5_DRIVE      (PSRAM_CTRL_BASE + 0x14)  /* drive strength */
#define PSRAM_REG8_CMD        (PSRAM_CTRL_BASE + 0x20)  /* 1=wr 2=rd 4=reset */
#define PSRAM_REG9_ADDR       (PSRAM_CTRL_BASE + 0x24)
#define PSRAM_REGA_WDATA      (PSRAM_CTRL_BASE + 0x28)
#define PSRAM_REGB_RDATA      (PSRAM_CTRL_BASE + 0x2c)

#define PSRAM_CMD_WRITE       (1u << 0)
#define PSRAM_CMD_READ        (1u << 1)
#define PSRAM_CMD_RESET       (1u << 2)

#define PSRAM_MODE7_OB9       0xd8054049ul   /* APS128XXO_OB9 mode word */
#define PSRAM_DRIVE_OB9       0x380ul
#define PSRAM_ID_OB9          0x8d08ul       /* MR0 identification */

/* System registers */

#define SYS_ANA_REG13         (BK7258_SYS_BASE + (0x4d << 2)) /* PSRAM LDO */
#define SYS_ANA_BUSY          (BK7258_SYS_BASE + (0x3a << 2)) /* bit13 */
#define SYS_POWER_SLEEP       (BK7258_SYS_BASE + (0x10 << 2)) /* AHBP bit5 */
#define SYS_CLK_DIV_MODE2     (BK7258_SYS_BASE + (0x09 << 2)) /* psram 4/5 */

#define ANA_PSLDO_SWB         (1u << 28)
#define ANA_VPSRAMSEL_MASK    (3u << 29)
#define ANA_ENPSRAM           (1u << 31)
#define ANA_BUSY_REG13        (1u << 13)     /* (0x4d - 0x40) */

#define PWD_AHBP              (1u << 5)

#define CKDIV_PSRAM           (1u << 4)      /* /2 within the recipe */
#define CKSEL_PSRAM_480M      (1u << 5)      /* 0 = 320M, 1 = 480M */

#define PSRAM_CKEN            (1u << 19)     /* device clk enable word */

#define PSRAM_POLL_BUDGET     50000

/****************************************************************************
 * Private Functions
 ****************************************************************************/

/* Write an analog register and wait for the hardware to latch it. */

static int psram_ana_write(uint32_t value)
{
  uint32_t budget = PSRAM_POLL_BUDGET;

  putreg32(value, SYS_ANA_REG13);

  while ((getreg32(SYS_ANA_BUSY) & ANA_BUSY_REG13) != 0)
    {
      if (--budget == 0)
        {
          return -1;
        }
    }

  return 0;
}

static int psram_cmd(uint32_t cmd)
{
  uint32_t budget = PSRAM_POLL_BUDGET;

  putreg32(cmd, PSRAM_REG8_CMD);

  while ((getreg32(PSRAM_REG8_CMD) & cmd) != 0)
    {
      if (--budget == 0)
        {
          return -1;
        }
    }

  return 0;
}

/* Read one PSRAM die mode register through the command engine. */

static int psram_mr_read(uint32_t addr, uint32_t *value)
{
  putreg32(addr, PSRAM_REG9_ADDR);

  if (psram_cmd(PSRAM_CMD_READ) < 0)
    {
      return -1;
    }

  *value = getreg32(PSRAM_REGB_RDATA);
  return 0;
}

static int psram_mr_write(uint32_t addr, uint32_t value)
{
  putreg32(addr, PSRAM_REG9_ADDR);
  putreg32(value, PSRAM_REGA_WDATA);
  return psram_cmd(PSRAM_CMD_WRITE);
}

/* Sanity: distinct patterns at spread-out addresses, written before any
 * is read back, so aliasing (address wrap) shows up as a mismatch.
 */

static int psram_selftest(void)
{
  static const uint32_t off[] =
  {
    0x0, 0x4, 0x100, 0x00800000, 0x00fffffc
  };

  volatile uint32_t *p;
  uint32_t i;

  for (i = 0; i < sizeof(off) / sizeof(off[0]); i++)
    {
      p  = (volatile uint32_t *)(PSRAM_DATA_BASE + off[i]);
      *p = off[i] ^ 0xa5a5a5a5u;
    }

  for (i = 0; i < sizeof(off) / sizeof(off[0]); i++)
    {
      p = (volatile uint32_t *)(PSRAM_DATA_BASE + off[i]);
      if (*p != (off[i] ^ 0xa5a5a5a5u))
        {
          return -1;
        }
    }

  return 0;
}

/****************************************************************************
 * Public Functions
 ****************************************************************************/

size_t bk7258_psram_init(void)
{
  uint32_t mr;
  uint32_t regval;
  int tries;

  /* LDO: voltage select first, then enable, each write latched. */

  regval  = getreg32(SYS_ANA_REG13);
  regval |= ANA_PSLDO_SWB;
  regval &= ~ANA_VPSRAMSEL_MASK;

  if (psram_ana_write(regval) < 0)
    {
      return 0;
    }

  up_udelay(100);

  if (psram_ana_write(regval | ANA_ENPSRAM) < 0)
    {
      return 0;
    }

  up_udelay(1000);

  /* AHBP power domain on (0 = powered). */

  modifyreg32(SYS_POWER_SLEEP, PWD_AHBP, 0);

  /* 80 MHz while configuring: 320 MHz source, recipe divider. */

  modifyreg32(SYS_CLK_DIV_MODE2, CKSEL_PSRAM_480M, CKDIV_PSRAM);

  /* Controller clock on. */

  modifyreg32(BK7258_SYS_CPU_DEVICE_CKEN, 0, PSRAM_CKEN);

  up_udelay(200);

  /* Controller: release reset, bypass, OB9 mode word, drive strength. */

  putreg32(1, PSRAM_REG2);
  modifyreg32(PSRAM_REG2, 0, 1u << 1);
  putreg32(PSRAM_MODE7_OB9, PSRAM_REG4_MODE);
  putreg32(PSRAM_DRIVE_OB9, PSRAM_REG5_DRIVE);

  psram_cmd(PSRAM_CMD_RESET);
  up_udelay(100);

  /* The die must identify before anything else is trusted. */

  for (tries = 0; tries < 5; tries++)
    {
      if (psram_mr_read(0x0, &mr) == 0 && mr == PSRAM_ID_OB9)
        {
          break;
        }

      putreg32(0, PSRAM_REG2);
      up_udelay(10);
      putreg32(1, PSRAM_REG2);
      modifyreg32(PSRAM_REG2, 0, 1u << 1);
      putreg32(PSRAM_MODE7_OB9, PSRAM_REG4_MODE);
      putreg32(PSRAM_DRIVE_OB9, PSRAM_REG5_DRIVE);
      psram_cmd(PSRAM_CMD_RESET);
      up_udelay(100);
    }

  if (tries >= 5)
    {
      return 0;
    }

  /* Latency tuning per the SDK: MR0[4:2]=100b (read latency),
   * MR4[7:5]=110b (write latency), MR8 |= 0x40.
   */

  if (psram_mr_write(0x0, (mr & ~(7u << 2)) | (4u << 2)) < 0)
    {
      return 0;
    }

  if (psram_mr_read(0x4, &mr) < 0 ||
      psram_mr_write(0x4, (mr & ~(7u << 5)) | (6u << 5)) < 0)
    {
      return 0;
    }

  if (psram_mr_read(0x8, &mr) < 0 ||
      psram_mr_write(0x8, mr | 0x40) < 0)
    {
      return 0;
    }

  up_udelay(1000);

  /* Full speed: 480 MHz source with the same divider -> 120 MHz. */

  modifyreg32(SYS_CLK_DIV_MODE2, 0, CKSEL_PSRAM_480M | CKDIV_PSRAM);

  up_udelay(100);

  if (psram_selftest() < 0)
    {
      return 0;
    }

  return PSRAM_SIZE;
}

